// Optional heartbeat for installation counting, not battery monitoring.
if (String(env.get("SEND_BIP") || "false").toLowerCase() !== "true") {
  node.status({fill:"grey",shape:"ring",text:"BIP disabled"});
  return null;
}
const id=String(env.get("SMART_JKBMS_INSTALL_ID")||"").trim();
const url=String(env.get("SMART_JKBMS_BIP_ENDPOINT")||"").trim();
const version=String(env.get("SMART_JKBMS_VERSION")||"").trim();
if (!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(id) || !url.startsWith("https://")) {
  node.status({fill:"yellow",shape:"ring",text:"BIP missing configuration"});
  return null;
}
msg.url=url;
msg.method="POST";
msg.headers={"Content-Type":"application/json"};
msg.followRedirects=false;
msg.payload={module:"jkbms",install_id:id,bip:"10",version:version};
node.status({fill:"blue",shape:"dot",text:"Sending BIP v"+version});
return msg;
